def _carrier_capture_macros(frame):
    """Return visible peg captures, including an empty bordered carrier."""
    slots, pegs = _peg_board(frame)
    carriers = {
        blob.top_left
        for blob in connected_components(frame, colors=(12,))
        if blob.size == (4, 4)
    }
    step = _lattice_step(slots | carriers)
    if not step:
        return ()
    destinations = slots | carriers
    macros = []
    for source in sorted(pegs):
        for dr, dc in ((-step, 0), (step, 0), (0, -step), (0, step)):
            jumped = (source[0] + dr, source[1] + dc)
            destination = (source[0] + 2 * dr, source[1] + 2 * dc)
            if (
                jumped in pegs
                and destination in destinations
                and destination not in pegs
            ):
                macros.append((
                    (6, source[1] + 1, source[0] + 1),
                    (6, destination[1] + 1, destination[0] + 1),
                ))
    return tuple(macros)


def solve_peg_solitaire_with_carrier(env, max_states=2000, max_depth=40):
    """Solve peg boards connected by a key-movable bordered carrier slot."""
    base_level = env.levels_completed

    def key(node):
        frame = arr(node.frame())
        return int(node.levels_completed), frame[1:, :].tobytes()

    queue = deque([(env.clone(), ())])
    seen = {key(env)}
    solution = None
    while queue and len(seen) < max_states:
        node, path = queue.popleft()
        if len(path) >= max_depth:
            continue
        macros = tuple((action,) for action in (1, 2, 3, 4))
        macros += _carrier_capture_macros(node.frame())
        for macro in macros:
            child = node.clone()
            for action in macro:
                play_action(child, action)
                if child.levels_completed > base_level:
                    solution = path + (macro,)
                    break
            if solution is not None:
                queue.clear()
                break
            child_key = key(child)
            if child_key not in seen:
                seen.add(child_key)
                queue.append((child, path + (macro,)))

    if solution is None:
        return
    for macro in solution:
        play_actions(env, macro)

def solve_bridge_carrier_peg_solitaire(
        env, max_align_states=120, max_macros=40, alignment_lookahead=24,
        alignment_lookaheads=None, trace=None):
    """Solve peg boards joined by persistent bridges and a movable carrier."""
    base_level = env.levels_completed
    node = env.clone()
    solution = []
    forbidden = set()

    def bridge_score(state, move):
        """Dense progress: distance from a bridge landing to another peg."""
        pegs = state[1]
        _, source, destination = move
        others = pegs - {source}
        if not others:
            return 10 ** 9
        return min(
            abs(destination[0] - peg[0]) + abs(destination[1] - peg[1])
            for peg in others
        )

    def choose_state(state, blocked):
        moves = _bridge_carrier_moves_from_state(state)
        captures = [move for move in moves if move[0] == "capture"]
        if captures:
            return captures[0]
        bridges = [
            move for move in moves
            if (move[1], move[2]) not in blocked
        ]
        if not bridges:
            return None
        best_score = min(bridge_score(state, move) for move in bridges)
        best = [
            move for move in bridges
            if bridge_score(state, move) == best_score
        ]
        return best[0]

    def choose(frame, blocked):
        return choose_state(_bridge_carrier_state(frame), blocked)

    def alignment_priority(state, path):
        slots, pegs = state[:2]
        ordered_pegs = sorted(pegs)
        distances = [
            abs(first[0] - second[0]) + abs(first[1] - second[1])
            for index, first in enumerate(ordered_pegs)
            for second in ordered_pegs[index + 1:]
        ]
        pair_distance = min(distances) if distances else 10 ** 9
        return -len(pegs), pair_distance, -len(slots), len(path)

    def alignment_path(root, blocked, lookahead):
        root_state = _bridge_carrier_state(root.frame())
        serial = 0
        queue = [(alignment_priority(root_state, ()), serial, ())]
        seen = {root_state}
        best_path = None
        best_score = None
        first_candidate_seen = None
        while queue and len(seen) < max_align_states:
            _, _, path = heappop(queue)
            if (
                first_candidate_seen is not None
                and len(seen) >= first_candidate_seen + lookahead
            ):
                return best_path
            for action in (4, 3, 2, 1):
                child_path = path + (action,)
                child = root.clone()
                play_actions(child, child_path)
                if child.levels_completed > base_level:
                    return child_path
                state = _bridge_carrier_state(child.frame())
                if state in seen:
                    continue
                seen.add(state)
                move = choose_state(state, blocked)
                if move is not None:
                    if move[0] == "capture":
                        return child_path
                    score = bridge_score(state, move)
                    if best_score is None or score < best_score:
                        best_path, best_score = child_path, score
                    if first_candidate_seen is None:
                        first_candidate_seen = len(seen)
                    step = _lattice_step(state[0] | state[2])
                    if step and score <= step:
                        return child_path
                if len(child_path) < 16:
                    serial += 1
                    heappush(
                        queue,
                        (alignment_priority(state, child_path), serial, child_path),
                    )
        return best_path

    for macro_index in range(max_macros):
        if node.levels_completed > base_level:
            break
        lookahead = alignment_lookahead
        if (
            alignment_lookaheads is not None
            and macro_index < len(alignment_lookaheads)
        ):
            lookahead = alignment_lookaheads[macro_index]
        move = choose(node.frame(), forbidden)
        if move is None:
            keys = alignment_path(node, forbidden, lookahead)
            if keys is None:
                if trace is not None:
                    trace.append(("alignment_failed", macro_index,
                                  len(solution)))
                return
            for action in keys:
                node.step(action)
                solution.append(action)
            if node.levels_completed > base_level:
                break
            move = choose(node.frame(), forbidden)
            if move is None:
                if trace is not None:
                    trace.append(("move_failed", macro_index, len(solution)))
                return
        kind, source, destination = move
        before = _bridge_carrier_state(node.frame())
        clicks = (
            (6, source[1] + 1, source[0] + 1),
            (6, destination[1] + 1, destination[0] + 1),
        )
        play_actions(node, clicks)
        solution.extend(clicks)
        after = _bridge_carrier_state(node.frame())
        if after == before:
            if trace is not None:
                trace.append(("click_failed", macro_index, move,
                              len(solution)))
            return
        if trace is not None:
            trace.append(("macro", macro_index, lookahead, move,
                          len(solution), len(after[1])))
        if kind == "bridge":
            forbidden.add((destination, source))
        else:
            forbidden.clear()

    if node.levels_completed <= base_level:
        if trace is not None:
            trace.append(("macro_limit", max_macros, len(solution)))
        return
    play_actions(env, solution)

"""Find shorter drop-in key paths between admitted coordinate macros."""

import json
import os
import sys
from collections import deque

sys.path.insert(0, "/Users/sasha/gkm/arc/crack_lab")
import gkm_arena as arena

from legs import _bridge_carrier_state
from perception import arr, safe_step


BOUNDARIES = (0, 8, 42, 87, 149, 238, 331, 476, 544)
KEYS = (1, 2, 3, 4, 7)


def state_key(node):
    if os.environ.get("COMPACT_KEY") == "1":
        return int(node.levels_completed), _bridge_carrier_state(node.frame())
    return int(node.levels_completed), arr(node.frame())[1:, :].tobytes()


def shorter_path(root, macro, pre_target_key, target_key, admitted_length,
                 max_states=None):
    if max_states is None:
        max_states = int(os.environ.get("MAX_STATES", "10000"))
    if admitted_length == 0:
        return None, 0
    queue = deque([(root.clone(), ())])
    seen = {state_key(root)}
    while queue and len(seen) <= max_states:
        node, path = queue.popleft()
        if state_key(node) == pre_target_key:
            probe = node.clone()
            for action in macro:
                safe_step(probe, action)
            if state_key(probe) == target_key:
                return path, len(seen)
        if len(path) >= admitted_length - 1:
            continue
        for action in KEYS:
            child = node.clone()
            safe_step(child, action)
            child_key = state_key(child)
            if child_key not in seen:
                seen.add(child_key)
                queue.append((child, path + (action,)))
    return None, len(seen)


def observe(env):
    level = int(os.environ.get("TARGET_LEVEL", "5"))
    target_macro = int(os.environ.get("TARGET_MACRO", "0"))
    with open("checkpoint.json") as stream:
        admitted = json.load(stream)["final_path"]
    start, end = BOUNDARIES[level - 1], BOUNDARIES[level]
    for action in admitted[:start]:
        env.step(action)

    current = env.clone()
    segment = admitted[start:end]
    index = 0
    macro_index = 0
    savings = 0
    replacements = []
    while index < len(segment):
        keys = []
        while index < len(segment) and not isinstance(segment[index], list):
            keys.append(segment[index])
            index += 1
        if index >= len(segment):
            break
        macro = tuple(tuple(action) for action in segment[index:index + 2])
        index += 2
        macro_index += 1

        start_node = current.clone()
        for action in keys:
            safe_step(current, action)
        pre_target = state_key(current)
        for action in macro:
            safe_step(current, action)
        target = state_key(current)

        if target_macro and macro_index != target_macro:
            shorter, states = None, 0
        else:
            shorter, states = shorter_path(
                start_node, macro, pre_target, target, len(keys)
            )
        if shorter is not None and len(shorter) < len(keys):
            savings += len(keys) - len(shorter)
            replacements.append((macro_index, tuple(keys), shorter))
        print("SEGMENT", {"macro": macro_index, "old": tuple(keys),
                          "shorter": shorter, "states": states,
                          "saving": 0 if shorter is None else
                          len(keys) - len(shorter)}, flush=True)

    print("SUMMARY", {"level": level, "savings": savings,
                      "replacements": replacements})


levels, path, error = arena.run_program("lf52", observe)
print("PROBE_RESULT", {"levels": levels, "moves": len(path), "error": str(error)})

