    for macro_index in range(max_macros):
        if node.levels_completed > base_level:
            break
        lookahead = alignment_lookahead
        if (
            alignment_lookaheads is not None
            and macro_index < len(alignment_lookaheads)
        ):
            lookahead = alignment_lookaheads[macro_index]
        move = choose(node.frame(), forbidden)
        if move is None:
            keys = alignment_path(node, forbidden, lookahead)
            if keys is None:
                if trace is not None:
                    trace.append(("alignment_failed", macro_index,
                                  len(solution)))
                return
            for action in keys:
                node.step(action)
                solution.append(action)
            if node.levels_completed > base_level:
                break
            move = choose(node.frame(), forbidden)
            if move is None:
                if trace is not None:
                    trace.append(("move_failed", macro_index, len(solution)))
                return
        kind, source, destination = move
        before = _bridge_carrier_state(node.frame())
        clicks = (
            (6, source[1] + 1, source[0] + 1),
            (6, destination[1] + 1, destination[0] + 1),
        )
        play_actions(node, clicks)
        solution.extend(clicks)
        after = _bridge_carrier_state(node.frame())
        if after == before:
            if trace is not None:
                trace.append(("click_failed", macro_index, move,
                              len(solution)))
            return
        if trace is not None:
            trace.append(("macro", macro_index, lookahead, move,
                          len(solution), len(after[1])))
        if kind == "bridge":
            forbidden.add((destination, source))
        else:
            forbidden.clear()

    if node.levels_completed <= base_level:
        if trace is not None:
            trace.append(("macro_limit", max_macros, len(solution)))
        return
    play_actions(env, solution)

