codex_turn_20260801T024901016230Z_lf52_L9_propose.jsonl:507:{"type":"item.completed","item":{"id":"item_297","type":"command_execution","command":"/bin/zsh -lc \"sed -n '1,165p' legs.py && sed -n '1,110p' players.py && sed -n '1,240p' probe_prefix_counts.py && sed -n '1,260p' probe_shorter_key_segments.py\"","aggregated_output":"# Shared leg library: small, named, reusable skills.\n# Players import from here; add a NEW leg only when no existing leg fits.\n\nfrom collections import deque\nfrom heapq import heappop, heappush\nfrom math import gcd\n\nfrom perception import arr, connected_components\n\n\ndef play_action(env, action):\n    \"\"\"Execute one key action or coordinate-click action.\"\"\"\n    if isinstance(action, tuple):\n        env.step(*action)\n    else:\n        env.step(action)\n\n\ndef play_actions(env, actions):\n    \"\"\"Execute key and coordinate-click actions in order.\"\"\"\n    for action in actions:\n        play_action(env, action)\n\n\ndef play_lattice_moves(env, moves):\n    \"\"\"Execute source/destination moves on the visible slot lattice.\"\"\"\n    for source, destination in moves:\n        play_actions(env, (\n            (6, source[1] + 1, source[0] + 1),\n            (6, destination[1] + 1, destination[0] + 1),\n        ))\n\n\ndef _peg_board(frame):\n    \"\"\"Return the slot lattice and occupied slots visible in a peg board.\"\"\"\n    holes = {\n        blob.top_left\n        for blob in connected_components(frame, colors=(1,))\n        if blob.size == (4, 4) and blob.area == 16\n    }\n    pegs = {\n        blob.top_left\n        for blob in connected_components(frame, colors=(14,))\n        if blob.size == (4, 4)\n    }\n    return holes | pegs, frozenset(pegs)\n\n\ndef _lattice_step(slots):\n    coordinates = [\n        sorted({position[axis] for position in slots})\n        for axis in (0, 1)\n    ]\n    differences = [\n        later - earlier\n        for values in coordinates\n        for earlier, later in zip(values, values[1:])\n        if later > earlier\n    ]\n    step = 0\n    for difference in differences:\n        step = gcd(step, difference)\n    return step\n\n\ndef _peg_solution(slots, start):\n    \"\"\"Find captures that leave the confirmed winning state of one peg.\"\"\"\n    step = _lattice_step(slots)\n    if not step:\n        return None\n    queue = deque([(start, ())])\n    seen = {start}\n    directions = ((-step, 0), (step, 0), (0, -step), (0, step))\n    while queue:\n        pegs, path = queue.popleft()\n        if len(pegs) == 1:\n            return path\n        for source in sorted(pegs):\n            for dr, dc in directions:\n                jumped = (source[0] + dr, source[1] + dc)\n                destination = (source[0] + 2 * dr, source[1] + 2 * dc)\n                if (\n                    jumped in pegs\n                    and destination in slots\n                    and destination not in pegs\n                ):\n                    child = frozenset((pegs - {source, jumped}) | {destination})\n                    if child not in seen:\n                        seen.add(child)\n                        queue.append((child, path + ((source, destination),)))\n    return None\n\n\ndef solve_peg_solitaire(env):\n    \"\"\"Solve a visible orthogonal peg-solitaire board using coordinate clicks.\"\"\"\n    slots, pegs = _peg_board(env.frame())\n    solution = _peg_solution(slots, pegs)\n    if solution is None:\n        return\n    play_lattice_moves(env, solution)\n\n\ndef _carrier_capture_macros(frame):\n    \"\"\"Return visible peg captures, including an empty bordered carrier.\"\"\"\n    slots, pegs = _peg_board(frame)\n    carriers = {\n        blob.top_left\n        for blob in connected_components(frame, colors=(12,))\n        if blob.size == (4, 4)\n    }\n    step = _lattice_step(slots | carriers)\n    if not step:\n        return ()\n    destinations = slots | carriers\n    macros = []\n    for source in sorted(pegs):\n        for dr, dc in ((-step, 0), (step, 0), (0, -step), (0, step)):\n            jumped = (source[0] + dr, source[1] + dc)\n            destination = (source[0] + 2 * dr, source[1] + 2 * dc)\n            if (\n                jumped in pegs\n                and destination in destinations\n                and destination not in pegs\n            ):\n                macros.append((\n                    (6, source[1] + 1, source[0] + 1),\n                    (6, destination[1] + 1, destination[0] + 1),\n                ))\n    return tuple(macros)\n\n\ndef solve_peg_solitaire_with_carrier(env, max_states=2000, max_depth=40):\n    \"\"\"Solve peg boards connected by a key-movable bordered carrier slot.\"\"\"\n    base_level = env.levels_completed\n\n    def key(node):\n        frame = arr(node.frame())\n        return int(node.levels_completed), frame[1:, :].tobytes()\n\n    queue = deque([(env.clone(), ())])\n    seen = {key(env)}\n    solution = None\n    while queue and len(seen) < max_states:\n        node, path = queue.popleft()\n        if len(path) >= max_depth:\n            continue\n        macros = tuple((action,) for action in (1, 2, 3, 4))\n        macros += _carrier_capture_macros(node.frame())\n        for macro in macros:\n            child = node.clone()\n            for action in macro:\n                play_action(child, action)\n                if child.levels_completed > base_level:\n                    solution = path + (macro,)\n                    break\n            if solution is not None:\n                queue.clear()\n                break\n            child_key = key(child)\n            if child_key not in seen:\n                seen.add(child_key)\n                queue.append((child, path + (macro,)))\n\n    if solution is None:\n        return\n# Per-level players. Each play_level_K(env) ONLY composes legs from legs.py.\nfrom legs import (\n    solve_grid_wrapped_bridge_carrier_peg_solitaire,\n    solve_parallel_wrapped_bridge_carrier_peg_solitaire,\n    solve_bridge_carrier_peg_solitaire,\n    solve_peg_solitaire,\n    solve_peg_solitaire_with_carrier,\n    solve_wrapped_bridge_carrier_peg_solitaire,\n    solve_walled_mixed_bridge_carrier_peg_solitaire,\n)\n\n\ndef play_level_1(env):\n    solve_peg_solitaire(env)\n\n\ndef play_level_2(env):\n    solve_peg_solitaire_with_carrier(env)\n\n\ndef play_level_3(env):\n    solve_peg_solitaire_with_carrier(env)\n\n\ndef play_level_4(env):\n    solve_bridge_carrier_peg_solitaire(\n        env, max_align_states=20, alignment_lookahead=3,\n    )\n\n\ndef play_level_5(env):\n    solve_bridge_carrier_peg_solitaire(env, max_align_states=650)\n\n\ndef play_level_6(env):\n    solve_wrapped_bridge_carrier_peg_solitaire(env)\n\n\ndef play_level_7(env):\n    solve_parallel_wrapped_bridge_carrier_peg_solitaire(env)\n\n\ndef play_level_8(env):\n    solve_grid_wrapped_bridge_carrier_peg_solitaire(env)\n\n\ndef play_level_9(env):\n    solve_walled_mixed_bridge_carrier_peg_solitaire(env)\n\"\"\"Fresh-replay real action counts at each solved level boundary.\"\"\"\n\nimport json\nimport sys\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\nimport gkm_arena as arena\n\ndef observe(env):\n    with open(\"checkpoint.json\") as stream:\n        path = json.load(stream)[\"final_path\"]\n    boundary = 0\n    for moves, action in enumerate(path, 1):\n        before = int(env.levels_completed)\n        env.step(action)\n        after = int(env.levels_completed)\n        if after > before:\n            print(\"BOUNDARY\", {\"level\": after, \"total\": moves,\n                               \"level_moves\": moves - boundary})\n            boundary = moves\n\n\nlevels, path, error = arena.run_program(\"lf52\", observe)\nprint(\"PROBE_RESULT\", {\"levels\": levels, \"moves\": len(path), \"error\": str(error)})\n\"\"\"Find shorter drop-in key paths between admitted coordinate macros.\"\"\"\n\nimport json\nimport os\nimport sys\nfrom collections import deque\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\nimport gkm_arena as arena\n\nfrom perception import arr, safe_step\n\n\nBOUNDARIES = (0, 8, 42, 87, 149, 238, 331, 476, 544)\nKEYS = (1, 2, 3, 4)\n\n\ndef state_key(node):\n    return int(node.levels_completed), arr(node.frame())[1:, :].tobytes()\n\n\ndef shorter_path(root, macro, target_key, admitted_length,\n                 max_states=10000):\n    if admitted_length == 0:\n        return None, 0\n    queue = deque([(root.clone(), ())])\n    seen = {state_key(root)}\n    while queue and len(seen) <= max_states:\n        node, path = queue.popleft()\n        probe = node.clone()\n        for action in macro:\n            safe_step(probe, action)\n        if state_key(probe) == target_key:\n            return path, len(seen)\n        if len(path) >= admitted_length - 1:\n            continue\n        for action in KEYS:\n            child = node.clone()\n            safe_step(child, action)\n            child_key = state_key(child)\n            if child_key not in seen:\n                seen.add(child_key)\n                queue.append((child, path + (action,)))\n    return None, len(seen)\n\n\ndef observe(env):\n    level = int(os.environ.get(\"TARGET_LEVEL\", \"5\"))\n    with open(\"checkpoint.json\") as stream:\n        admitted = json.load(stream)[\"final_path\"]\n    start, end = BOUNDARIES[level - 1], BOUNDARIES[level]\n    for action in admitted[:start]:\n        env.step(action)\n\n    current = env.clone()\n    segment = admitted[start:end]\n    index = 0\n    macro_index = 0\n    savings = 0\n    replacements = []\n    while index < len(segment):\n        keys = []\n        while index < len(segment) and not isinstance(segment[index], list):\n            keys.append(segment[index])\n            index += 1\n        if index >= len(segment):\n            break\n        macro = tuple(tuple(action) for action in segment[index:index + 2])\n        index += 2\n        macro_index += 1\n\n        start_node = current.clone()\n        for action in keys:\n            safe_step(current, action)\n        for action in macro:\n            safe_step(current, action)\n        target = state_key(current)\n\n        shorter, states = shorter_path(start_node, macro, target, len(keys))\n        if shorter is not None and len(shorter) < len(keys):\n            savings += len(keys) - len(shorter)\n            replacements.append((macro_index, tuple(keys), shorter))\n        print(\"SEGMENT\", {\"macro\": macro_index, \"old\": tuple(keys),\n                          \"shorter\": shorter, \"states\": states,\n                          \"saving\": 0 if shorter is None else\n                          len(keys) - len(shorter)})\n\n    print(\"SUMMARY\", {\"level\": level, \"savings\": savings,\n                      \"replacements\": replacements})\n\n\nlevels, path, error = arena.run_program(\"lf52\", observe)\nprint(\"PROBE_RESULT\", {\"levels\": levels, \"moves\": len(path), \"error\": str(error)})\n","exit_code":0,"status":"completed"}}
