me):\n    holes, bridges, pegs, carriers, supports = lattice(frame)\n    destinations = holes | carriers\n    occupied = bridges | pegs | supports\n    moves = []\n    for kind, pieces in ((\"bridge\", bridges), (\"peg\", pegs)):\n        for source in sorted(pieces):\n            for delta_row, delta_col in (\n                (-6, 0), (6, 0), (0, -6), (0, 6)\n            ):\n                midpoint = (\n                    source[0] + delta_row,\n                    source[1] + delta_col,\n                )\n                destination = (\n                    source[0] + 2 * delta_row,\n                    source[1] + 2 * delta_col,\n                )\n                if midpoint in occupied and destination in destinations:\n                    moves.append((kind, source, destination))\n    return tuple(moves)\n\n\ndef move_actions(source, destination):\n    return (\n        [6, source[1] + 1, source[0] + 1],\n        [6, destination[1] + 1, destination[0] + 1],\n    )\n\n\ndef apply_move(node, move):\n    kind, source, destination = move\n    child = node.clone()\n    for action in move_actions(source, destination):\n        play(child, action)\n    if child.levels_completed > 8:\n        return child\n    color = 9 if kind == \"bridge\" else 14\n    array = np.asarray(child.frame())\n\n    def piece_count(position):\n        row, col = position\n        return int(np.count_nonzero(array[row:row + 4, col:col + 4] == color))\n\n    if piece_count(source) >= 12 or piece_count(destination) < 12:\n        return None\n    return child\n\n\ndef dense_summary(node):\n    _, bridges, pegs, carriers, supports = lattice(node.frame())\n    distances = [\n        abs(left[0] - right[0]) + abs(left[1] - right[1])\n        for left in pegs\n        for right in pegs\n        if left != right\n    ]\n    return (\n        len(pegs),\n        min(distances, default=999),\n        len(bridges),\n        len(carriers),\n        len(supports),\n    )\n\n\ndef search(root):\n    serial = 0\n    queue = [(0, serial, [], root.clone(), None)]\n    best_cost = {physical_key(root): 0}\n    best_dense = (dense_summary(root), 0, [])\n    expanded = 0\n    while queue and expanded < MAX_STATES:\n        cost, _, path, node, forbidden = heapq.heappop(queue)\n        if cost > MAX_COST:\n            break\n        key = physical_key(node)\n        if cost != best_cost.get(key):\n            continue\n        expanded += 1\n        dense = dense_summary(node)\n        if dense < best_dense[0]:\n            best_dense = (dense, cost, path)\n            print(\"DENSE\", {\n                \"expanded\": expanded,\n                \"cost\": cost,\n                \"dense\": dense,\n                \"tail\": path[-8:],\n            }, flush=True)\n        if node.levels_completed > 8:\n            return path, expanded, len(best_cost), best_dense\n\n        children = []\n        if cost + 1 <= MAX_COST:\n            for action in (3, 4):\n                if forbidden == (\"key\", action):\n                    continue\n                edge_actions = [action]\n                child = node.clone()\n                play(child, action)\n                if physical_key(child) != key:\n                    inverse = (\"key\", 4 if action == 3 else 3)\n                    children.append((1, child, edge_actions, inverse))\n        if cost + 2 <= MAX_COST:\n            for move in visible_moves(node.frame()):\n                if forbidden == (\"move\", move[0], move[1], move[2]):\n                    continue\n                edge_actions = list(move_actions(move[1], move[2]))\n                child = node.clone()\n                for action in edge_actions:\n                    play(child, action)\n                if child.levels_completed <= 8:\n                    color = 9 if move[0] == \"bridge\" else 14\n                    array = np.asarray(child.frame())\n\n                    def piece_count(position):\n                        row, col = position\n                        return int(np.count_nonzero(\n                            array[row:row + 4, col:col + 4] == color\n                        ))\n\n                    if (\n                        piece_count(move[1]) >= 12\n                        or piece_count(move[2]) < 12\n                    ):\n                        child = None\n                if child is not None:\n                    inverse = (\n                        \"move\", move[0], move[2], move[1]\n                    )\n                    children.append((2, child, edge_actions, inverse))\n\n        for edge_cost, child, edge_actions, inverse in children:\n            child_cost = cost + edge_cost\n            if child_cost > MAX_COST:\n                continue\n            child_key = physical_key(child)\n            if child_cost >= best_cost.get(child_key, MAX_COST + 1):\n                continue\n            best_cost[child_key] = child_cost\n            serial += 1\n            child_path = path + edge_actions\n            if child.levels_completed > 8:\n                return child_path, expanded, len(best_cost), best_dense\n            heapq.heappush(\n                queue,\n                (child_cost, serial, child_path, child, inverse),\n            )\n\n        if expanded % 250 == 0:\n            print(\"PROGRESS\", {\n                \"expanded\": expanded,\n                \"seen\": len(best_cost),\n                \"frontier_cost\": cost,\n            }, flush=True)\n    return None, expanded, len(best_cost), best_dense\n\n\ndef probe(env):\n    with open(\"checkpoint.json\") as checkpoint_file:\n        prefix = json.load(checkpoint_file)[\"final_path\"]\n    entry_file = (\n        \"level9_entry_variant_candidate.json\"\n        if ENTRY_VARIANT else\n        \"level9_candidate_102.json\"\n    )\n    with open(entry_file) as candidate_file:\n        entry_actions = json.load(candidate_file)[:28]\n    for action in prefix:\n        play(env, action)\n    node = env.clone()\n    for action in entry_actions:\n        play(node, action)\n    print(\"ENTRY\", {\n        \"variant\": ENTRY_VARIANT,\n        \"dense\": dense_summary(node),\n        \"moves\": visible_moves(node.frame()),\n    }, flush=True)\n    path, expanded, seen, best_dense = search(node)\n    print(\"SEARCH\", {\n        \"path\": path,\n        \"cost\": len(path) if path else None,\n        \"expanded\": expanded,\n        \"seen\": seen,\n        \"best_dense\": best_dense,\n    }, flush=True)\n\n\nif __name__ == \"__main__\":\n    levels, path, error = arena.run_program(\"lf52\", probe)\n    print(\"HARNESS\", {\n        \"levels\": levels,\n        \"moves\": len(path),\n        \"error\": str(error) if error else None,\n    })\n\"\"\"Match partial fixed-leg prefixes to cheaper native suffix entry states.\"\"\"\n\nimport json\nimport sys\n\nimport numpy as np\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\n\nimport gkm_arena as arena\n\nfrom legs import (\n    _bridge_carrier_state,\n    _movable_bridge_board,\n    solve_direct_bridge_carrier_peg_solitaire,\n    solve_grid_wrapped_bridge_carrier_peg_solitaire,\n    solve_multi_bridge_wrapped_carrier_peg_solitaire,\n    solve_parallel_wrapped_bridge_carrier_peg_solitaire,\n    solve_wrapped_bridge_carrier_peg_solitaire,\n)\n\n\nENTRIES = {5: 149, 6: 238, 7: 331, 8: 476, 9: 544}\nNATIVE_FILES = {\n    6: \"level6_greedy_macro_candidate.json\",\n    7: \"level7_greedy_macro_candidate.json\",\n    8: \"level8_greedy_macro_candidate.json\",\n    9: \"level9_candidate_102.json\",\n}\nSTAGING = (\n    solve_direct_bridge_carrier_peg_solitaire,\n    solve_wrapped_bridge_carrier_peg_solitaire,\n    solve_grid_wrapped_bridge_carrier_peg_solitaire,\n    solve_parallel_wrapped_bridge_carrier_peg_solitaire,\n    solve_multi_bridge_wrapped_carrier_peg_solitaire,\n)\n\n\nclass RecordingEnv:\n    def __init__(self, base):\n        self.base = base\n        self.actions_taken = []\n\n    def step(self, *action):\n        self.actions_taken.append(\n            list(action) if len(action) > 1 else action[0]\n        )\n        return self.base.step(*action)\n\n    def clone(self):\n        return RecordingEnv(self.base.clone())\n\n    def __getattr__(self, name):\n        return getattr(self.base, name)\n\n\ndef play(env, action):\n    if isinstance(action, list):\n        env.step(*action)\n    else:\n        env.step(action)\n\n\ndef macro_units(actions):\n    units = []\n    index = 0\n    while index < len(actions):\n        if isinstance(actions[index], list):\n            units.append((actions[index], actions[index + 1]))\n            index += 2\n        else:\n            units.append((actions[index],))\n            index += 1\n    return units\n\n\ndef flatten(units):\n    return [action for unit in units for action in unit]\n\n\ndef keys(env):\n    frame = np.asarray(env.frame()).copy()\n    frame[0, :] = 0\n    full = frame.tobytes()\n    bridge = _bridge_carrier_state(env.frame())\n    movable = tuple(\n        frozenset(part) for part in _movable_bridge_board(env.frame())\n    )\n    abstract = (bridge, movable)\n    relaxed = (\n        bridge[1], bridge[2], bridge[3], bridge[4],\n        movable[1], movable[2], movable[3],\n    )\n    return full, abstract, relaxed\n\n\ndef trace(entry, units):\n    node = entry.clone()\n    states = [(0, 0, keys(node))]\n    action_cost = 0\n    for unit_index, unit in enumerate(units, 1):\n        for action in unit:\n            play(node, action)\n            action_cost += 1\n        states.append((unit_index, action_cost, keys(node)))\n        if node.levels_completed > entry.levels_completed:\n            break\n    return states\n\n\ndef native_actions(level, campaign):\n    if level == 5:\n        return campaign[149:238]\n    with open(NATIVE_FILES[level]) as native_file:\n        return json.load(native_file)\n\n\ndef probe(env):\n    with open(\"checkpoint.json\") as checkpoint_file:\n        campaign = json.load(checkpoint_file)[\"final_path\"]\n    entries = {}\n    node = env.clone()\n    for index, action in enumerate(campaign):\n        if index in ENTRIES.values():\n            level = next(\n                level for level, point in ENTRIES.items() if point == index\n            )\n            entries[level] = node.clone()\n        play(node, action)\n    entries[9] = node.clone()\n    winners = []\n    for level in range(5, 10):\n        native = native_actions(level, campaign)\n        native_units = macro_units(native)\n        native_trace = trace(entries[level], native_units)\n        for staging_solver in STAGING:\n            recorder = RecordingEnv(entries[level].clone())\n            staging_solver(recorder)\n            staging_units = macro_units(recorder.actions_taken)\n            staging_trace = trace(entries[level], staging_units)\n            candidates = set()\n            for stage_unit, stage_cost, stage_keys in staging_trace:\n                for native_unit, native_cost, native_keys in native_trace:\n                    if stage_cost >= native_cost:\n                        continue\n                    match_kind = next((\n                        name for name, index in (\n                            (\"full\", 0), (\"abstract\", 1), (\"relaxed\", 2)\n                        )\n                        if stage_keys[index] == native_keys[index]\n                    ), None)\n                    if match_kind is not None:\n                        candidates.add((\n                            stage_unit, native_unit, match_kind,\n                            stage_cost, native_cost,\n                        ))\n            for (\n                stage_unit, native_unit, match_kind,\n                stage_cost, native_cost,\n            ) in sorted(candidates, key=lambda item: (item[3], -item[4])):\n                trial = entries[level].clone()\n                prefix = flatten(staging_units[:stage_unit])\n                suffix = flatten(native_units[native_unit:])\n                for action in prefix:\n                    play(trial, action)\n                executed = []\n                for action in suffix:\n                    play(trial, action)\n                    executed.append(action)\n                    if trial.levels_completed > level - 1:\n                        break\n                if trial.levels_completed > level - 1:\n                    candidate = prefix + executed\n                    if len(candidate) >= len(native):\n                        continue\n                    winners.append((level, staging_solver.__name__, candidate))\n                    print(\"WIN\", {\n                        \"level\": level,\n                        \"staging\": staging_solver.__name__,\n                        \"match\": match_kind,\n                        \"costs\": (stage_cost, native_cost),\n                        \"native\": len(native),\n                        \"candidate\": len(candidate),\n                    }, flush=True)\n            print(\"MATCHES\", {\n                \"level\": level,\n                \"staging\": staging_solver.__name__,\n                \"candidates\": len(candidates),\n            }, flush=True)\n    for level, staging_name, candidate in winners:\n        filename = f\"level{level}_partial_splice_{len(candidate)}.json\"\n        with open(filename, \"w\") as candidate_file:\n            json.dump(candidate, candidate_file, indent=2)\n            candidate_file.write(\"\\n\")\n        print(\"SAVED\", {\n            \"level\": level,\n            \"staging\": staging_name,\n            \"file\": filename,\n        })\n    print(\"RESULT\", {\"winners\": len(winners)})\n\n\nlevels, path, error = arena.run_program(\"lf52\", probe)\nprint(\"HARNESS\", {\n    \"levels\": levels,\n    \"moves\": len(path),\n    \"error\": str(error) if error else None,\n})\n\"\"\"Find shorter drop-in key paths between admitted coordinate macros.\"\"\"\n\nimport json\nimport os\nimport sys\nfrom collections import deque\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\nimport gkm_arena as arena\n\nfrom perception import arr, safe_step\n\n\nBOUNDARIES = (0, 8, 42, 87, 149, 238, 331, 476, 544)\nKEYS = (1, 2, 3, 4)\n\n\ndef state_key(node):\n    return int(node.levels_completed), arr(node.frame())[1:, :].tobytes()\n\n\ndef shorter_path(root, macro, target_key, admitted_length,\n                 max_states=10000):\n    if admitted_length == 0:\n        return None, 0\n    queue = deque([(root.clone(), ())])\n    seen = {state_key(root)}\n    while queue and len(seen) <= max_states:\n        node, path = queue.popleft()\n        probe = node.clone()\n        for action in macro:\n            safe_step(probe, action)\n        if state_key(probe) == target_key:\n            return path, len(seen)\n        if len(path) >= admitted_length - 1:\n            continue\n        for action in KEYS:\n            child = node.clone()\n            safe_step(child, action)\n            child_key = state_key(child)\n            if child_key not in seen:\n                seen.add(child_key)\n                queue.append((child, path + (action,)))\n    return None, len(seen)\n\n\ndef observe(env):\n    level = int(os.environ.get(\"TARGET_LEVEL\", \"5\"))\n    with open(\"checkpoint.json\") as stream:\n        admitted = json.load(stream)[\"final_path\"]\n    start, end = BOUNDARIES[level - 1], BOUNDARIES[level]\n    for action in admitted[:start]:\n        env.step(action)\n\n    current = env.clone()\n    segment = admitted[start:end]\n    index = 0\n    macro_index = 0\n    savings = 0\n    replacements = []\n    while index < len(segment):\n        keys = []\n        while index < len(segment) and not isinstance(segment[index], list):\n            keys.append(segment[index])\n            index += 1\n        if index >= len(segment):\n            break\n        macro = tuple(tuple(action) for action in segment[index:index + 2])\n        index += 2\n        macro_index += 1\n\n        start_node = current.clone()\n        for action in keys:\n            safe_step(current, action)\n        for action in macro:\n            safe_step(current, action)\n        target = state_key(current)\n\n        shorter, states = shorter_path(start_node, macro, target, len(keys))\n        if shorter is not None and len(shorter) < len(keys):\n            savings += len(keys) - len(shorter)\n            replacements.append((macro_index, tuple(keys), shorter))\n        print(\"SEGMENT\", {\"macro\": macro_index, \"old\": tuple(keys),\n                          \"shorter\": shorter, \"states\": states,\n                          \"saving\": 0 if shorter is None else\n                          len(keys) - len(shorter)})\n\n    print(\"SUMMARY\", {\"level\": level, \"savings\": savings,\n                      \"replacements\": replacements})\n\n\nlevels, path, error = arena.run_program(\"lf52\", observe)\nprint(\"PROBE_RESULT\", {\"levels\": levels, \"moves\": len(path), \"error\": str(error)})\n","exit_code":0,"status":"completed"}}
