codex_turn_20260801T074734645734Z_lf52_L9_propose.jsonl:137:{"type":"item.completed","item":{"id":"item_80","type":"command_execution","command":"/bin/zsh -lc \"sed -n '1,380p' probe_suffix_splices.py\nsed -n '1,360p' probe_cycle_remove.py\nsed -n '1,360p' probe_greedy_macro_deletions.py\"","aggregated_output":"\"\"\"Reward-test shorter fixed-leg prefixes against every native macro suffix.\"\"\"\n\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\n\nimport gkm_arena as arena\n\nfrom legs import (\n    solve_direct_bridge_carrier_peg_solitaire,\n    solve_grid_wrapped_bridge_carrier_peg_solitaire,\n)\n\n\nENTRIES = {5: 149, 6: 238, 7: 331, 8: 476, 9: 544}\nNATIVE_FILES = {\n    6: \"level6_greedy_macro_candidate.json\",\n    7: \"level7_greedy_macro_candidate.json\",\n    8: \"level8_greedy_macro_candidate.json\",\n    9: \"level9_candidate_102.json\",\n}\nSTAGING = (\n    solve_direct_bridge_carrier_peg_solitaire,\n    solve_grid_wrapped_bridge_carrier_peg_solitaire,\n)\nTARGET_LEVELS = tuple(\n    int(level)\n    for level in os.environ.get(\"SPLICE_LEVELS\", \"5,6,7,8,9\").split(\",\")\n)\n\n\nclass RecordingEnv:\n    def __init__(self, base):\n        self.base = base\n        self.actions_taken = []\n\n    def step(self, *action):\n        self.actions_taken.append(\n            list(action) if len(action) > 1 else action[0]\n        )\n        return self.base.step(*action)\n\n    def clone(self):\n        return RecordingEnv(self.base.clone())\n\n    def __getattr__(self, name):\n        return getattr(self.base, name)\n\n\ndef play(env, action):\n    if isinstance(action, list):\n        env.step(*action)\n    else:\n        env.step(action)\n\n\ndef macro_units(actions):\n    units = []\n    index = 0\n    while index < len(actions):\n        if isinstance(actions[index], list):\n            units.append((actions[index], actions[index + 1]))\n            index += 2\n        else:\n            units.append((actions[index],))\n            index += 1\n    return units\n\n\ndef flatten(units):\n    return [action for unit in units for action in unit]\n\n\ndef probe(env):\n    with open(\"checkpoint.json\") as checkpoint_file:\n        campaign = json.load(checkpoint_file)[\"final_path\"]\n    entries = {}\n    node = env.clone()\n    for index, action in enumerate(campaign):\n        if index in ENTRIES.values():\n            level = next(\n                level for level, point in ENTRIES.items() if point == index\n            )\n            entries[level] = node.clone()\n        play(node, action)\n    entries[9] = node.clone()\n    winners = []\n    for level in TARGET_LEVELS:\n        if level == 5:\n            native = campaign[149:238]\n        else:\n            with open(NATIVE_FILES[level]) as native_file:\n                native = json.load(native_file)\n        native_units = macro_units(native)\n        for staging in STAGING:\n            staged = RecordingEnv(entries[level].clone())\n            staging(staged)\n            staging_actions = staged.actions_taken\n            if staged.levels_completed > level - 1:\n                continue\n            for cut in range(len(native_units) + 1):\n                suffix = flatten(native_units[cut:])\n                trial = staged.base.clone()\n                executed = []\n                for action in suffix:\n                    play(trial, action)\n                    executed.append(action)\n                    if trial.levels_completed > level - 1:\n                        break\n                if trial.levels_completed > level - 1:\n                    candidate = staging_actions + executed\n                    if len(candidate) >= len(native):\n                        continue\n                    winners.append((level, staging.__name__, cut, candidate))\n                    print(\"WIN\", {\n                        \"level\": level,\n                        \"staging\": staging.__name__,\n                        \"cut\": cut,\n                        \"native\": len(native),\n                        \"candidate\": len(candidate),\n                    }, flush=True)\n    for level, staging_name, cut, candidate in winners:\n        filename = f\"level{level}_splice_{len(candidate)}.json\"\n        with open(filename, \"w\") as candidate_file:\n            json.dump(candidate, candidate_file, indent=2)\n            candidate_file.write(\"\\n\")\n        print(\"SAVED\", {\n            \"level\": level,\n            \"staging\": staging_name,\n            \"cut\": cut,\n            \"file\": filename,\n        })\n    print(\"RESULT\", {\n        \"winners\": len(winners),\n        \"best\": {\n            level: min(\n                len(candidate)\n                for winner_level, _, _, candidate in winners\n                if winner_level == level\n            )\n            for level in sorted({winner[0] for winner in winners})\n        },\n    })\n\n\nlevels, path, error = arena.run_program(\"lf52\", probe)\nprint(\"HARNESS\", {\n    \"levels\": levels,\n    \"moves\": len(path),\n    \"error\": str(error) if error else None,\n})\n\"\"\"Find and validate removable repeated-frame cycles in one level path.\"\"\"\n\nimport json\nimport os\nimport sys\nfrom collections import defaultdict\n\nimport numpy as np\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\nimport gkm_arena as arena\n\n\nBOUNDARIES = (0, 8, 42, 87, 149, 238, 331, 476, 544)\n\n\ndef frame_key(node):\n    return np.asarray(node.frame())[1:, :].tobytes()\n\n\ndef observe(env):\n    level = int(os.environ.get(\"TARGET_LEVEL\", \"7\"))\n    with open(\"checkpoint.json\") as stream:\n        admitted = json.load(stream)[\"final_path\"]\n    start, end = BOUNDARIES[level - 1], BOUNDARIES[level]\n    for action in admitted[:start]:\n        env.step(action)\n    root = env.clone()\n    segment = admitted[start:end]\n\n    cursor = root.clone()\n    occurrences = defaultdict(list)\n    occurrences[frame_key(cursor)].append(0)\n    for index, action in enumerate(segment, 1):\n        cursor.step(action)\n        occurrences[frame_key(cursor)].append(index)\n\n    intervals = []\n    for indices in occurrences.values():\n        for left_index, first in enumerate(indices):\n            for last in indices[left_index + 1:]:\n                intervals.append((last - first, first, last))\n    intervals.sort(reverse=True)\n\n    tested = 0\n    solution = None\n    for saving, first, last in intervals[:500]:\n        tested += 1\n        candidate = root.clone()\n        path = segment[:first] + segment[last:]\n        for action in path:\n            if candidate.terminal():\n                break\n            candidate.step(action)\n        if candidate.levels_completed >= level:\n            solution = (saving, first, last, path)\n            break\n\n    print(\"CYCLES\", {\"level\": level, \"repeated_intervals\": len(intervals),\n                     \"tested\": tested,\n                     \"saving\": None if solution is None else solution[0],\n                     \"first\": None if solution is None else solution[1],\n                     \"last\": None if solution is None else solution[2],\n                     \"path\": None if solution is None else solution[3]})\n\n\nlevels, path, error = arena.run_program(\"lf52\", observe)\nprint(\"PROBE_RESULT\", {\"levels\": levels, \"moves\": len(path), \"error\": str(error)})\n\"\"\"Greedily test individual atomic-macro deletions in a bounded index range.\"\"\"\n\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, \"/Users/sasha/gkm/arc/crack_lab\")\n\nimport gkm_arena as arena\n\n\nENTRY_INDEX = int(os.environ.get(\"GREEDY_ENTRY\", \"331\"))\nSTART_INDEX = int(os.environ.get(\"GREEDY_START\", \"0\"))\nEND_INDEX = int(os.environ.get(\"GREEDY_END\", \"40\"))\nBASE_FILE = os.environ.get(\n    \"GREEDY_BASE\", \"level7_macro_ddmin_candidate.json\"\n)\nOUTPUT_FILE = os.environ.get(\n    \"GREEDY_OUTPUT\", \"level7_greedy_macro_candidate.json\"\n)\n\n\ndef macro_units(actions):\n    units = []\n    index = 0\n    while index < len(actions):\n        action = actions[index]\n        if isinstance(action, list):\n            units.append((action, actions[index + 1]))\n            index += 2\n        else:\n            units.append((action,))\n            index += 1\n    return units\n\n\ndef flatten(units):\n    return [action for unit in units for action in unit]\n\n\ndef play(env, action):\n    if isinstance(action, list):\n        env.step(*action)\n    else:\n        env.step(action)\n\n\ndef winning_prefix(entry, units):\n    node = entry.clone()\n    base_level = node.levels_completed\n    for unit_index, unit in enumerate(units, 1):\n        for action in unit:\n            play(node, action)\n        if node.levels_completed > base_level:\n            return list(units[:unit_index])\n    return None\n\n\ndef save(units):\n    with open(OUTPUT_FILE, \"w\") as output_file:\n        json.dump(flatten(units), output_file, indent=2)\n        output_file.write(\"\\n\")\n\n\ndef probe(env):\n    with open(\"checkpoint.json\") as checkpoint_file:\n        campaign = json.load(checkpoint_file)[\"final_path\"]\n    with open(BASE_FILE) as base_file:\n        current = macro_units(json.load(base_file))\n    for action in campaign[:ENTRY_INDEX]:\n        play(env, action)\n    entry = env.clone()\n    index = START_INDEX\n    tests = 0\n    while index < min(END_INDEX, len(current)):\n        tests += 1\n        result = winning_prefix(\n            entry, current[:index] + current[index + 1:]\n        )\n        if result is not None:\n            before = len(flatten(current))\n            current = result\n            save(current)\n            print(\"IMPROVE\", {\n                \"index\": index,\n                \"actions\": (before, len(flatten(current))),\n                \"file\": OUTPUT_FILE,\n            }, flush=True)\n            continue\n        index += 1\n    save(current)\n    print(\"RESULT\", {\n        \"range\": (START_INDEX, END_INDEX),\n        \"tests\": tests,\n        \"actions\": len(flatten(current)),\n        \"verified\": winning_prefix(entry, current) is not None,\n        \"file\": OUTPUT_FILE,\n    })\n\n\nlevels, path, error = arena.run_program(\"lf52\", probe)\nprint(\"HARNESS\", {\n    \"levels\": levels,\n    \"moves\": len(path),\n    \"error\": str(error) if error else None,\n})\n","exit_code":0,"status":"completed"}}
